import{_ as o,o as a,c as e,a5 as n}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频","日期":"2026-04-09T00:00:00.000Z","修改日期":"2026-05-26T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["音频视频批处理"],"标签":["ts视频合并","合并ts文件","批量合并ts","批量合并ts视频","批量合并视频"]},"headers":[{"level":2,"title":"102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频","slug":"_102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频","link":"#_102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频","children":[{"level":3,"title":"📑 程序截图","slug":"📑-程序截图","link":"#📑-程序截图","children":[]},{"level":3,"title":"📑 使用场景例子展示","slug":"📑-使用场景例子展示","link":"#📑-使用场景例子展示","children":[]},{"level":3,"title":"📑 程序使用环境及相关说明","slug":"📑-程序使用环境及相关说明","link":"#📑-程序使用环境及相关说明","children":[]},{"level":3,"title":"程序配置(很重要)","slug":"程序配置-很重要","link":"#程序配置-很重要","children":[]},{"level":3,"title":"程序文件截图","slug":"程序文件截图","link":"#程序文件截图","children":[]},{"level":3,"title":"程序更新日志：","slug":"程序更新日志","link":"#程序更新日志","children":[]}]}],"relativePath":"md/音频视频批处理/102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频.md","filePath":"md/音频视频批处理/102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频.md"}'),s={name:"md/音频视频批处理/102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频.md"};function l(r,t,p,i,u,_){return a(),e("div",null,[...t[0]||(t[0]=[n('<h2 id="_102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频" tabindex="-1">102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频 <a class="header-anchor" href="#_102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频" aria-label="Permalink to &quot;102-批量合并ts及视频流视频片段-及其他相同格式相同流的视频&quot;">​</a></h2><p>批量合并ts文件，指定A文件夹下有B、C....等文件夹，</p><p>选择1时，将A文件夹下所有ts视频合并为一个视频，合并后的文件名为：final_output.mp4</p><p>选择2时，B、C....等文件夹下视频分别合并在各自文件夹下，文件名为：原文件名_final_output.mp4</p><p><strong>支持的文件格式：</strong> &quot;.avi&quot;, &quot;.mp4&quot;, &quot;.mov&quot;,  &quot;.wmv&quot;,&quot;.flv&quot;,  &quot;.mkv&quot;, &quot;.ts&quot;,  &quot;.webm&quot;,  &quot;.m4v&quot;,&quot;.asf&quot; 只支持这些格式相同视频的合并，</p><p>不支持跨格式视频合并。</p><p><strong>需要同格式的情况下合并</strong>，或者是同一个视频拆分的视频合并，或者视频尺寸、分别率、音频流相同的情况下合并。</p><p>**▶是否支持子文件夹穿透：支持 **</p><p>**注意：**先测试备份原文件再批量使用</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250114233520173686892013280.png" alt=""></p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多支持的文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有支持的文件。</p><p><strong>选择1时</strong>，将A文件夹下所有ts视频合并为一个视频，合并后的文件名为：final_output.mp4</p><p><strong>选择2时</strong>，B、C....等文件夹下视频分别合并在各自文件夹下，文件名为：原文件名_final_output.mp4</p><p><strong>需要同格式的情况下合并</strong>，或者是同一个视频拆分的视频合并（如解析下载的额ts视频流），或者在视频尺寸、分别率、音频流相同的情况下合并（即视频流与音频流相同的情况下才可以）。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="程序配置-很重要" tabindex="-1">程序配置(很重要) <a class="header-anchor" href="#程序配置-很重要" aria-label="Permalink to &quot;程序配置(很重要)&quot;">​</a></h3><p>将<strong>apitool</strong>文件夹复制到C盘根目录下，效果为：<strong>C:\\apitool</strong></p><p><strong>演示图如下所示：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-32.png" alt=""></p><h3 id="程序文件截图" tabindex="-1">程序文件截图 <a class="header-anchor" href="#程序文件截图" aria-label="Permalink to &quot;程序文件截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-36.png" alt=""></p><h3 id="程序更新日志" tabindex="-1">程序更新日志： <a class="header-anchor" href="#程序更新日志" aria-label="Permalink to &quot;程序更新日志：&quot;">​</a></h3><p>修复一些问题-20260526</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/625.html" target="_blank" rel="noreferrer">https://www.softbangong.com/625.html</a></p>',28)])])}const c=o(s,[["render",l]]);export{h as __pageData,c as default};
